export const validateExpandSeeds = (vs: ReadonlyArray<CuratedExpandVenue> = BUCHAREST_EXPAND) => {
  for (const v of vs) {
    if (!v.venueName.trim() || !v.address.trim()) throw new Error("venueName+address required");
    if (!v.newSpaces.length) throw new Error(`${v.venueName}: no new spaces`);
    const names = new Set<string>();
    for (const s of v.newSpaces) {
      if (!s.shortDescription.trim() || !s.description.trim()) throw new Error(`${v.venueName}/${s.name}: copy required`);
      for (const a of s.amenityNames) if (!ALLOWED.has(a)) throw new Error(`${v.venueName}/${s.name}: bad amenity ${a}`);
      if (names.has(s.name)) throw new Error(`${v.venueName}: dup space ${s.name}`);
      names.add(s.name);
    }
  }
};
